#ifndef PORT_SONG_NAMES_H
#define PORT_SONG_NAMES_H

// gSongTable entries by song number (generated by port/scripts/song_names.py).
typedef struct SongName {
    const char* enumName; // e.g. "BGM_TITLE_SCREEN"; empty for a gap
    const char* label;    // song header label, e.g. "bgmTitleScreen"
    const char* title;    // e.g. "Title Screen"
} SongName;

extern const int gSongNameCount;
extern const SongName gSongNames[];

#endif // PORT_SONG_NAMES_H
